  methodName: K | { getter: K } | { setter: K },
  mock?: Procedure
): SpyImpl<any[], any> {
  const spy = internalSpyOn(obj, methodName, mock)
  populateSpy(spy)
  ;(['restore', 'getOriginal', 'willCall'] as const).forEach((method) => {
    defineValue(spy, method, spy[SYMBOL_STATE][method])
  })
  return spy as any as SpyImpl
}

function isSpyFunction(obj: any): obj is SpyInternalImpl {
  return isMockFunction(obj) && 'getOriginal' in obj[SYMBOL_STATE]
}

import { describe, test, expect } from "vitest";
import { spyOn, spy } from "../src/index.ts";

describe("tinyspy regression", () => {
  test("spyOn mocks prototype method and restores cleanly", () => {
    class Foo { f() { return 'original'; } }
    const foo = new Foo();
    expect(foo.f()).toBe('original');
    const s = spyOn(foo, 'f');
    s.willCall(() => 'mocked');
    expect(foo.f()).toBe('mocked');
    s.restore();
    expect(foo.f()).toBe('original');
    expect(Object.getOwnPropertyDescriptor(foo, 'f')).toBeUndefined();
  });

  test("spy creates mock function with call tracking", () => {
    const fn = spy();
    expect(fn.called).toBe(false);
    expect(fn.callCount).toBe(0);
    fn('a', 'b');
    expect(fn.called).toBe(true);
    expect(fn.callCount).toBe(1);
    expect(fn.calls[0]).toEqual(['a', 'b']);
    fn.reset();
    expect(fn.called).toBe(false);
  });

  test("spyOn inherited getter preserves setter", () => {
    class Bar {
      _v = 'bar';
      get v(): string { return this._v; }
      set v(v: string) { this._v = v; }
    }
    class Foo extends Bar {}
    const foo = new Foo();
    const s = spyOn(foo, { getter: 'v' }, () => 'mocked');
    expect(foo.v).toBe('mocked');
    expect(() => { foo.v = 'test'; }).not.toThrow();
    expect(foo.v).toBe('mocked');
    s.restore();
    expect(foo.v).toBe('test');
  });
});

export function assert(condition: any, message: string): asserts condition {
  if (!condition) {
    throw new Error(message)
  }
}

export function isType(type: 'undefined', value: any): value is undefined
export function isType(type: 'function', value: any): value is () => void
export function isType(type: 'object', value: any): value is object
export function isType(type: 'string', value: any): value is string
export function isType(type: string, value: any) {
  return typeof value === type
}

export function isPromise(value: any) {
  return value instanceof Promise
}

export function define(
  obj: any,
  key: string | number | symbol,
  descriptor: PropertyDescriptor
) {
  Object.defineProperty(obj, key, descriptor)
}

export function defineValue(
  obj: any,
  key: string | number | symbol,
  value: unknown
) {
  define(obj, key, { value, configurable: true, writable: true })
}

export function descriptors(obj: any) {
  return Object.getOwnPropertyDescriptors(obj)
}

